def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    denominator = 2

    try:
        value = (v1 + v2) / denominator
    except ZeroDivisionError:
        return None

    return {
        "value": value,
        "trace": {
            "v1": v1,
            "v2": v2,
            "count": denominator,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": "currency"
            }
        }
    }
